{"content": "     1|/**
     2| * Go (围棋) Game Plugin — Skeleton
     3| * 19×19, capture rules, liberty counting
     4| * Status: coming_soon — AI not implemented
     5| */
     6|export const PLUGIN_ID = 'go'
     7|export const BOARD_SIZE = 19
     8|
     9|export function createBoard() {
    10|  return Array.from({ length: BOARD_SIZE }, () => new Array(BOARD_SIZE).fill(0))
    11|}
    12|
    13|function inBounds(r, c) { return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE }
    14|const DIRS = [[-1,0],[1,0],[0,-1],[0,1]]
    15|
    16|export function getGroup(board, r, c) {
    17|  const player = board[r][c]
    18|  if (!player) return new Set()
    19|  const group = new Set()
    20|  const stack = [[r, c]]
    21|  while (stack.length) {
    22|    const [cr, cc] = stack.pop()
    23|    const key = `${cr},${cc}`
    24|    if (group.has(key)) continue
    25|    if (!inBounds(cr, cc) || board[cr][cc] !== player) continue
    26|    group.add(key)
    27|    for (const [dr, dc] of DIRS) stack.push([cr+dr, cc+dc])
    28|  }
    29|  return group
    30|}
    31|
    32|export function countLiberties(board, group) {
    33|  const libs = new Set()
    34|  for (const key of group) {
    35|    const [r, c] = key.split(',').map(Number)
    36|    for (const [dr, dc] of DIRS) {
    37|      const nr = r+dr, nc = c+dc
    38|      if (inBounds(nr, nc) && board[nr][nc] === 0) libs.add(`${nr},${nc}`)
    39|    }
    40|  }
    41|  return libs.size
    42|}
    43|
    44|export function applyMove(board, r, c, player) {
    45|  if (board[r][c] !== 0) return null
    46|  const next = board.map(row => [...row])
    47|  next[r][c] = player
    48|  const opp = 3 - player
    49|  let captured = 0
    50|  for (const [dr, dc] of DIRS) {
    51|    const nr = r+dr, nc = c+dc
    52|    if (inBounds(nr, nc) && next[nr][nc] === opp) {
    53|      const grp = getGroup(next, nr, nc)
    54|      if (countLiberties(next, grp) === 0) {
    55|        for (const key of grp) {
    56|          const [gr, gc] = key.split(',').map(Number)
    57|          next[gr][gc] = 0
    58|          captured++
    59|        }
    60|      }
    61|    }
    62|  }
    63|  // suicide check
    64|  const myGrp = getGroup(next, r, c)
    65|  if (countLiberties(next, myGrp) === 0) return null
    66|  return { board: next, captured }
    67|}
    68|
    69|export function estimateScore(board, komi = 6.5) {
    70|  let black = 0, white = 0
    71|  for (let r = 0; r < BOARD_SIZE; r++)
    72|    for (let c = 0; c < BOARD_SIZE; c++) {
    73|      if (board[r][c] === 1) black++
    74|      else if (board[r][c] === 2) white++
    75|    }
    76|  return { black, white: white + komi }
    77|}
    78|
    79|export async function getBestMove(board, player, difficulty = 'medium') {
    80|  const { getBestMove: mctsBest } = await import('./mcts.js')
    81|  return mctsBest(board, player, difficulty)
    82|}
